/**
 * Which prototype files the keyframes come from, and the generated module each group goes to.
 * `generate-keyframes.ts` writes them; a test regenerates them in memory and compares.
 */
import { type Keyframes } from '../src/motion/keyframes';
import { keyframeBodies, parseKeyframes, readDesign } from './css';

export interface KeyframeGroup {
  /** The generated file stem in `src/motion/keyframes/`. */
  readonly file: string;
  /** The exported constant. */
  readonly exportName: string;
  /** What the group is, for the file's doc comment. */
  readonly about: string;
  /** Prototype files (relative to `design/prototype/`) and, optionally, the names taken from each. */
  readonly sources: readonly { readonly file: string; readonly names?: readonly string[] }[];
}

export const keyframeGroups: readonly KeyframeGroup[] = [
  {
    file: 'screens',
    exportName: 'screenKeyframes',
    about: 'the first-week prototype, `design/prototype/Yapling Week 1.dc.html`',
    sources: [{ file: 'Yapling Week 1.dc.html' }],
  },
  {
    file: 'shared',
    exportName: 'sharedKeyframes',
    about:
      'the shared helpers in `design/prototype/art/yap-dc.js` (critter idles, stamps, panels, doors), plus the roommate jump of the onboarding board',
    sources: [
      { file: 'art/yap-dc.js' },
      { file: 'boards/Yapling R4 Onboarding.dc.html', names: ['yjump'] },
    ],
  },
  {
    file: 'hub',
    exportName: 'hubKeyframes',
    about:
      'the hub prototype, `design/prototype/Yapling Prototype.dc.html` (town map, incoming call, Me sheet, Plus)',
    sources: [{ file: 'Yapling Prototype.dc.html' }],
  },
];

/** The keyframes of one group, parsed from the prototype, in source order. */
export function groupKeyframes(group: KeyframeGroup): Keyframes[] {
  const bodies = new Map<string, string>();
  for (const { file, names } of group.sources) {
    for (const [name, body] of keyframeBodies(readDesign(file))) {
      if (names && !names.includes(name)) continue;
      const seen = bodies.get(name);
      if (seen !== undefined && seen !== body)
        throw new Error(`@keyframes ${name} differs within ${group.file}`);
      bodies.set(name, body);
    }
  }
  return [...bodies].map(([name, body]) => parseKeyframes(name, body));
}

function literal(value: unknown): string {
  if (typeof value === 'number') return Object.is(value, -0) ? '0' : String(value);
  if (typeof value === 'string') return `'${value}'`;
  if (Array.isArray(value)) return `[${value.map(literal).join(', ')}]`;
  if (value && typeof value === 'object') {
    const entries = Object.entries(value).map(
      ([k, v]) => `${/^\w+$/.test(k) ? k : `'${k}'`}: ${literal(v)}`,
    );
    return entries.length === 0 ? '{}' : `{ ${entries.join(', ')} }`;
  }
  throw new Error(`cannot write ${String(value)}`);
}

/** The source of one generated module. */
export function keyframeModuleSource(
  group: KeyframeGroup,
  keyframes: readonly Keyframes[],
): string {
  const lines = [
    '// Generated by `pnpm --filter @yapling/theme gen` from the design prototype. Do not edit;',
    '// re-run the generator after a design sync.',
    "import type { Keyframes } from '../keyframes';",
    '',
    `/** Every \`@keyframes\` of ${group.about}, by its CSS name. */`,
    `export const ${group.exportName} = {`,
  ];
  for (const k of keyframes) {
    lines.push(
      `  ${/^\w+$/.test(k.name) ? k.name : `'${k.name}'`}: {`,
      `    name: '${k.name}',`,
      `    transform: ${literal(k.transform)},`,
      '    tracks: {',
    );
    for (const [channel, stops] of Object.entries(k.tracks)) {
      lines.push(`      ${channel}: ${literal(stops)},`);
    }
    lines.push('    },', '  },');
  }
  lines.push('} as const satisfies Record<string, Keyframes>;', '');
  return lines.join('\n');
}
